import numpy as np
import pandas as pd

def fit(train: pd.DataFrame, target: str, seed: int) -> object:
    # Compute the mean of the target on the training data
    mean_val = train[target].mean()
    # Return a simple object that stores the mean
    return {'mean': mean_val}

def predict(model: object, X: pd.DataFrame) -> np.ndarray:
    # Predict the mean for every row
    return np.full(shape=(len(X),), fill_value=model['mean'], dtype=float)

